BEGIN TRANSACTION;
CREATE TABLE event_staff (
	event_id INTEGER NOT NULL, 
	staff_id INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	requested_at DATETIME NOT NULL, 
	reviewed_at DATETIME, 
	reviewed_by INTEGER, 
	PRIMARY KEY (event_id, staff_id), 
	FOREIGN KEY(event_id) REFERENCES events (id), 
	FOREIGN KEY(staff_id) REFERENCES users (id), 
	FOREIGN KEY(reviewed_by) REFERENCES users (id)
);
INSERT INTO "event_staff" VALUES(1,5,'pending','2026-10-15 11:32:47.136115',NULL,NULL);
CREATE TABLE events (
	id INTEGER NOT NULL, 
	title VARCHAR(80) NOT NULL, 
	description TEXT NOT NULL, 
	date VARCHAR(10) NOT NULL, 
	time VARCHAR(5) NOT NULL, 
	location VARCHAR(150) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	max_participants INTEGER NOT NULL, 
	image_url VARCHAR(255), 
	status VARCHAR(20), 
	organizer_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(organizer_id) REFERENCES users (id)
);
INSERT INTO "events" VALUES(1,'Festa da Tuga','Prepara-te para viver a noite mais portuguesa do ano! O Festival da Tuga chega para reunir o melhor da nossa identidade, da nossa música e do nosso espírito festivo num evento inesquecível.

Se és fã dos grandes clássicos que toda a gente sabe cantar de cor, dos ritmos populares que não deixam ninguém parado, do funk e dos êxitos nacionais do momento, este festival é para ti!','2026-12-15','12:12','Rua Paúl de Pedroso, n.º 22, 4415-340 Pedroso','Entertainment',134,'data:image/png;base64,','active',4);
CREATE TABLE favorites (
	user_id INTEGER NOT NULL, 
	event_id INTEGER NOT NULL, 
	PRIMARY KEY (user_id, event_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(event_id) REFERENCES events (id)
);
INSERT INTO "favorites" VALUES(4,1);
CREATE TABLE follow_requests (
	requester_id INTEGER NOT NULL, 
	target_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (requester_id, target_id), 
	FOREIGN KEY(requester_id) REFERENCES users (id), 
	FOREIGN KEY(target_id) REFERENCES users (id)
);
CREATE TABLE organizer_follows (
	follower_id INTEGER NOT NULL, 
	organizer_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (follower_id, organizer_id), 
	FOREIGN KEY(follower_id) REFERENCES users (id), 
	FOREIGN KEY(organizer_id) REFERENCES users (id)
);
INSERT INTO "organizer_follows" VALUES(5,4,'2026-10-15 11:32:36.052594');
CREATE TABLE registrations (
	user_id INTEGER NOT NULL, 
	event_id INTEGER NOT NULL, 
	created_at DATETIME, ticket_code VARCHAR(32), checked_in_at DATETIME, checked_in_by INTEGER, 
	PRIMARY KEY (user_id, event_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(event_id) REFERENCES events (id)
);
INSERT INTO "registrations" VALUES(3,1,'2026-10-15 11:34:13.896433','7a397a3668e14754ba802a961c5c07c9',NULL,NULL);
CREATE TABLE user_blocks (
	blocker_id INTEGER NOT NULL, 
	blocked_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (blocker_id, blocked_id), 
	FOREIGN KEY(blocker_id) REFERENCES users (id), 
	FOREIGN KEY(blocked_id) REFERENCES users (id)
);
CREATE TABLE user_mutes (
	muter_id INTEGER NOT NULL, 
	muted_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (muter_id, muted_id), 
	FOREIGN KEY(muter_id) REFERENCES users (id), 
	FOREIGN KEY(muted_id) REFERENCES users (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	hashed_password VARCHAR(200) NOT NULL, 
	avatar_url VARCHAR(255), phone_number VARCHAR(30), country VARCHAR(80), city VARCHAR(80), role VARCHAR(20) NOT NULL DEFAULT 'attendee', bio TEXT, preferred_categories TEXT NOT NULL DEFAULT '[]', brand_name VARCHAR(100), website_url VARCHAR(255), instagram_url VARCHAR(255), contact_email VARCHAR(120), username VARCHAR(40), is_public INTEGER NOT NULL DEFAULT 1, x_url VARCHAR(255), linkedin_url VARCHAR(255), spotify_url VARCHAR(255), tiktok_url VARCHAR(255), cover_image TEXT, profile_theme VARCHAR(7) NOT NULL DEFAULT '#7c5cff', avatar_frame VARCHAR(20) NOT NULL DEFAULT 'none', pronouns VARCHAR(40), status_message VARCHAR(120), show_interests INTEGER NOT NULL DEFAULT 1, show_attended_events INTEGER NOT NULL DEFAULT 1, show_network INTEGER NOT NULL DEFAULT 1, featured_event_id INTEGER, profile_location VARCHAR(120), show_attendance_count INTEGER NOT NULL DEFAULT 1, 
	PRIMARY KEY (id)
);
